S.profile=({role})=>head('Personal','Your profile & account','')+`<div class="columns"><form class="panel pad stack" data-demo-form="Profile saved in this prototype only."><h2>Team profile</h2>${field('Display name',input('display-name','Alex Chen'))}${field('Department',select('profile-department',['Software','Mechanical','Electrical','Design','Business','Outreach']))}${field('Grade / year',input('grade','11'))}${field('Avatar URL',input('avatar-url','','url'))}${field('Bio','<textarea name="bio">Software team · Autonomous development</textarea>')}${manager(role)?field('Displayed role',select('displayed-role',['Officer','Leadership','Member']),'Cosmetic only. Never grants authority; cannot exceed your real role.'):''}<button class="button primary">Save profile</button></form><div class="stack"><section class="panel pad"><h2>Account</h2><details style="margin-top:12px"><summary>Account email</summary><p class="small muted">alex.chen@example.test · Verified<br>Linked identity: Email</p></details><hr class="divider"><p class="small"><strong>Authority:</strong> ${role==='president'?'President · Full authority':role==='admin'?'Officer · Explicit domain grants in this review':role==='lead'?'Member · Assigned lead for Library robotics day':'Member'}</p></section><form class="panel pad stack" data-demo-form="Password change simulated; no real credentials changed."><h2>Change password</h2>${field('New password','<input type="password" name="new-password" autocomplete="new-password" minlength="6" required>','At least six characters under the current application contract.')}<button class="button">Change password</button></form>${button('View sign-in & admission screens','onboarding')}</div></div>`;
